/* Lime tokens. The one file to retune.

   Lime is a light system for consumer apps with one acid yellow-green accent: a white page,
   warm-grey surfaces, near-black text, no blue. The one gradient is the glow: see Glow below.

   Rules
   - Lime is for the primary action, the chosen thing, a highlight and focus. It is never a page, card or
     section background. Everything else is white, warm grey and ink.
   - Text on the accent is --on-accent, near-black, in both themes. Black on the mark is 15.6:1.
   - The accent has five steps. mark: the fill of a primary action. hover and active: its states.
     wash: a selected row, a highlighted answer, a soft chip. line: a darker olive for focus rings,
     outlines and icons on white (3.95:1 on the page, 3.62:1 on a warm-grey surface). The mark alone is
     1.23:1 on white, so it never draws a line or a ring on a light surface.
   - Status keeps its own hues (green, amber, red). There is no info hue, so there is no blue.
   - Components read roles, never hex and never a dark: variant. The dark theme redefines the roles.
   - No gradients, with one deliberate exception: the glow, a solid accent body lit from inside, on the primary
     action, the balance chip and one featured card. Shadows are a warm ink at low alpha and appear on overlays
     and raised cards only.

   Format, read by the docs
   - One declaration per line: --name: value; followed by a comment of the form job | used by.
   - A line that starts with == opens a token group. Keep both formats when you retune.

   Font: Hanken Grotesk, SIL OFL, from Google Fonts. */

@import url("https://fonts.googleapis.com/css2?family=Hanken+Grotesk:wght@400;500;600&display=swap");

[data-system="lime"], .lime {
  /* == Surfaces == */
  --page: #ffffff; /* the page | app background */
  --surface: #f6f5f2; /* warm grey: cards, wells, quiet panels | card, sidebar, table header */
  --surface-2: #efeeea; /* a control at rest or a row on hover | secondary button, chip, hover */
  --surface-3: #e6e4df; /* pressed, a track | pressed control, slider and switch track */
  --raised: #ffffff; /* a surface that floats above the page | popover, menu, dialog, sheet */
  --field: #f6f5f2; /* the fill of a text field | input, textarea, select trigger */
  --scrim: rgb(15 15 13 / 0.5); /* the layer behind a dialog or sheet | dialog, sheet */

  /* == Text == */
  --fg: #0f0f0d; /* primary text, 17.6:1 on --surface | headings, body, labels */
  --fg-2: #4a4943; /* secondary text, 9.0:1 on --page | descriptions, table cells */
  --fg-3: #6b6a63; /* supporting text and icons, 5.4:1 on --page and 5.0:1 on --surface | hints, captions, placeholders */
  --fg-disabled: #a6a49b; /* a disabled label; no contrast claim | disabled controls */
  --fg-inverse: #ffffff; /* text on the solid ink fill | solid button, tooltip, toast */
  --on-accent: #0f0f0d; /* text and icons on the lime in both themes, 15.6:1 on --accent | primary button, selected chip */
  --glow-accent-fg: #0f0f0d; /* text and icons on the lime glow: ink, on the light body and the calmer dark one alike (Customize turns it white for a picked hue whose dark body runs deep) | primary button, balance chip, featured card */

  /* == Lines == */
  --line: #e6e4df; /* a hairline between things; decorative | card edge, divider, table rule */
  --line-strong: #cfcdc6; /* a hairline that must read a little more | field edge, hovered edge */
  --control: #85827a; /* the outline of a control, 3.8:1 on --page, 3.5:1 on --surface and 3.3:1 on --surface-2, all over the minimum of WCAG 1.4.11; darkened one step from #8f8c84, which fell under it on --surface-2 | checkbox, radio, switch off, slider thumb */

  /* == Solid ink == */
  --ink: #0f0f0d; /* the ink fill: the second action beside the lime | solid button, tooltip, toast */
  --ink-hover: #2a2a26; /* ink on hover | solid button */
  --ink-active: #3f3f3a; /* ink pressed | solid button */

  /* == Accent: acid lime == */
  --accent: #e4f222; /* the mark: the fill of a primary action, 15.6:1 with --on-accent | primary button, selected segment, switch on, slider fill, progress */
  --accent-hover: #d6e41a; /* the mark on hover, 13.7:1 with --on-accent | primary button */
  --accent-active: #c4d211; /* the mark pressed, 11.5:1 with --on-accent | primary button */
  --accent-wash: #f5f9c4; /* a soft highlight, 17.6:1 with --fg | selected row, highlighted option, the current answer */
  --accent-line: #7c8700; /* olive line step, 3.95:1 on --page and 3.62:1 on --surface | focus ring, outline, icon on white */
  --ring: var(--accent-line); /* the focus ring colour | every focus-visible state */

  /* == Status: three hues, each with a mark, a tint and a text step == */
  --success: #1e8e4a; /* success mark, 4.2:1 on --page | status dot, progress done */
  --success-tint: #e5f5ea; /* success wash | success badge, alert */
  --success-text: #17703a; /* success text, 6.1:1 on --page and 5.4:1 on --success-tint | success label */
  --warn: #c27a00; /* warning mark, 3.5:1 on --page | status dot */
  --warn-tint: #fff3d6; /* warning wash | warning badge, alert */
  --warn-text: #8a5200; /* warning text, 6.4:1 on --page and 5.8:1 on --warn-tint | warning label */
  --danger: #d93636; /* error fill, 4.6:1 with --on-danger | destructive button, invalid ring */
  --danger-hover: #c02c2c; /* error fill on hover, 5.8:1 with --on-danger | destructive button */
  --danger-tint: #fdebeb; /* error wash | error badge, alert */
  --on-danger: #ffffff; /* text on the error fill | destructive button */
  --danger-text: #b42323; /* error text, 6.6:1 on --page and 5.7:1 on --danger-tint | error message, error label */

  /* == Elevation: a warm ink, low alpha == */
  --shadow-ink: 40 36 20; /* the shadow channel | every shadow */
  --shadow-card: 0 1px 2px rgb(var(--shadow-ink) / 0.06), 0 1px 1px rgb(var(--shadow-ink) / 0.04); /* a raised card | card with the raised prop */
  --shadow-menu: 0 8px 24px -6px rgb(var(--shadow-ink) / 0.16), 0 2px 6px rgb(var(--shadow-ink) / 0.06); /* a menu, popover or select popup | popover, dropdown-menu, select, combobox */
  --shadow-overlay: 0 24px 48px -12px rgb(var(--shadow-ink) / 0.24), 0 4px 12px rgb(var(--shadow-ink) / 0.08); /* a dialog or sheet | dialog, alert-dialog, sheet */
  --thumb: #ffffff; /* the knob of a switch, white | switch */
  --switch-on: var(--accent); /* a switch's track when on | switch */
  --switch-on-thumb: var(--thumb); /* a switch's knob when on: white on the lime | switch */
  --shadow-thumb: 0 2px 5px rgb(var(--shadow-ink) / 0.1), 0 1px 1px rgb(var(--shadow-ink) / 0.07), 0 0 0 0.5px rgb(var(--shadow-ink) / 0.1); /* the knob's lift, like a phone's switch: a soft drop, a contact shadow and a hairline edge | switch */

  /* == Glow: a lit surface == */
  --glow-accent-from: #dbec1c; /* top of the lime body, black text 15.1:1 at the darkest stop | primary button, balance chip, featured card */
  --glow-accent-to: #f6ff7c; /* bottom of the lime body | primary button, balance chip, featured card */
  --glow-accent-edge: rgb(255 255 255 / 0.7); /* the crisp light line on the lower inner edge | glow-accent */
  --glow-accent-bloom: rgb(255 255 255 / 0.28); /* the soft inner bloom | glow-accent */
  --glow-accent-cast: 112 120 20; /* the olive outer cast, an RGB triplet | glow-accent */
  --glow-accent-light: 1; /* strength of the white sheen and bloom on the body | glow-accent */
  --glow-accent-from-lit: #e4f42c; /* top of the body when powered on (hover), black text 16.3:1 at the darkest stop | glow-accent */
  --glow-accent-to-lit: #faff9c; /* bottom of the body when powered on | glow-accent */
  --glow-accent-edge-lit: rgb(255 255 255 / 0.9); /* the lower edge line when powered on | glow-accent */
  --glow-accent-bloom-lit: rgb(255 255 255 / 0.4); /* the inner bloom when powered on | glow-accent */
  --glow-accent-from-press: #c8d915; /* top of the body while pressed, a darker body, black text 12.4:1 at the darkest stop | glow-accent */
  --glow-accent-to-press: #e6f24a; /* bottom of the body while pressed | glow-accent */
  --glow-danger-from: #a31f1f; /* top of the red body, white text 6.1:1 at the worst point | destructive button */
  --glow-danger-to: #c42b2b; /* bottom of the red body | destructive button */
  --glow-danger-edge: rgb(255 255 255 / 0.4); /* the lower edge line | glow-danger */
  --glow-danger-bloom: rgb(255 255 255 / 0.16); /* the inner bloom | glow-danger */
  --glow-danger-cast: 130 30 30; /* the red outer cast | glow-danger */
  --glow-danger-light: 0.4; /* a dimmer sheen, so white text keeps 4.5:1 | glow-danger */
  --glow-danger-from-lit: #b02424; /* top when powered on, white text 5.2:1 at the worst point | glow-danger */
  --glow-danger-to-lit: #d03333; /* bottom when powered on | glow-danger */
  --glow-danger-edge-lit: rgb(255 255 255 / 0.6); /* the lower edge line when powered on | glow-danger */
  --glow-danger-bloom-lit: rgb(255 255 255 / 0.24); /* the inner bloom when powered on | glow-danger */
  --glow-danger-from-press: #8a1818; /* top while pressed, white text 7.6:1 at the worst point | glow-danger */
  --glow-danger-to-press: #a82121; /* bottom while pressed | glow-danger */
  --glow-success-from: #136b35; /* top of the green body, white text 5.2:1 at the worst point | glow-success */
  --glow-success-to: #1a8445; /* bottom of the green body | glow-success */
  --glow-success-edge: rgb(255 255 255 / 0.4); /* the lower edge line | glow-success */
  --glow-success-bloom: rgb(255 255 255 / 0.16); /* the inner bloom | glow-success */
  --glow-success-cast: 20 100 55; /* the green outer cast | glow-success */
  --glow-success-light: 0.4; /* a dimmer sheen, so white text keeps 4.5:1 | glow-success */
  --glow-success-fg: #ffffff; /* text on the green body | glow-success */
  --glow-success-from-lit: #126f39; /* top when powered on, white text 4.6:1 at the worst point | glow-success */
  --glow-success-to-lit: #1a8445; /* bottom when powered on | glow-success */
  --glow-success-edge-lit: rgb(255 255 255 / 0.6); /* the lower edge line when powered on | glow-success */
  --glow-success-bloom-lit: rgb(255 255 255 / 0.24); /* the inner bloom when powered on | glow-success */
  --glow-success-from-press: #0f5a2b; /* top while pressed, white text 6.5:1 at the worst point | glow-success */
  --glow-success-to-press: #157038; /* bottom while pressed | glow-success */

  /* == Type == */
  --font-sans: "Hanken Grotesk", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif; /* every word | all text */
  --font-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace; /* code and keys only | code, shortcut */
  --text-xs: 12px; /* captions, counters | badge, hint */
  --text-sm: 14px; /* controls and body | button, input, menu item */
  --text-base: 16px; /* prose, large controls | message, large button */
  --text-lg: 18px; /* a small heading | card title, empty title */
  --text-xl: 22px; /* a section or overlay heading | page section, dialog, alert-dialog and sheet titles */
  --text-2xl: 28px; /* a page heading | page title */
  --text-3xl: 36px; /* a display figure | account balance */
  --leading-tight: 1.2; /* headings | text-lg and up */
  --leading-snug: 1.35; /* labels and short copy | button, card */
  --leading-normal: 1.5; /* prose | body */
  --tracking-tight: -0.01em; /* large headings only; Lime never tracks out | text-xl and up */
  --weight-normal: 400; /* body | prose */
  --weight-medium: 500; /* controls and labels | button, label */
  --weight-semibold: 600; /* headings | titles */

  /* == Size: the control height ramp == */
  --control-sm: 32px; /* a compact control | sm button, chip, input */
  --control-md: 40px; /* the default control | button, input, select */
  --control-lg: 48px; /* a primary mobile action | lg button, chat input */

  /* == Radius: controls are pills, fields and panels are soft == */
  --radius-sm: 6px; /* a tiny inner shape | kbd, checkbox */
  --radius-md: 10px; /* a menu item | menu item, tab list inner */
  --radius-field: 12px; /* a text field | input, textarea, select trigger */
  --radius-panel: 16px; /* a card, popover or dialog | card, popover, dialog, alert */
  --radius-sheet: 24px; /* a dialog or sheet | dialog, sheet */
  --radius-control: 999px; /* a button, chip, badge, segment | button, chip, badge, segmented */

  /* == Motion: short, ease-out, never decorative == */
  --dur-instant: 80ms; /* hover and press colour | every control */
  --dur-fast: 140ms; /* a small state change | switch, chip, checkbox */
  --dur-base: 200ms; /* a popup or tab opening | popover, menu, tooltip */
  --dur-slow: 280ms; /* a dialog or sheet moving | dialog, sheet */
  --dur-spin: 900ms; /* one turn of the spinner, the only looping motion | spinner */
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1); /* the house curve | all transitions */
  --ease-in: cubic-bezier(0.4, 0, 1, 1); /* an element leaving | closing popups */
  --scale-enter: 0.97; /* a popup's starting scale | popover, menu, dialog */
  --scale-press: 0.98; /* a control's scale while pressed | button, balance, keypad key */

  /* == Layers: what sits above what == */
  --z-dialog: 40; /* a dialog or sheet and its scrim | dialog, alert-dialog, sheet */
  --z-popover: 50; /* a popup anchored to a control, above the dialog it opens from | popover, menu, select, combobox, tooltip */
  --z-toast: 60; /* a toast, above everything else | toast */

  /* == Layout == */
  --overlay-sm: 384px; /* a small dialog | alert-dialog */
  --overlay: 480px; /* the default dialog | dialog */
  --overlay-lg: 640px; /* a wide dialog | dialog size lg */
  --popover: 320px; /* a popover's width | popover */
  --sheet: 400px; /* a side sheet's width, so the page stays in view beside it | sheet */
  --popup-max: 320px; /* the tallest a list popup grows before it scrolls | select, combobox, menu */
  --focus-offset: 2px; /* the gap between a control and its ring | every focus-visible state */
  --line-focus: 2px; /* the ring weight | every focus-visible state */
  --scrollbar-thumb: var(--line-strong); /* the scrollbar thumb | scroll-area, native scrollbars */
}

/* The dark theme redefines the roles. The lime steps down a little in lightness and saturation so it does not glare
   on a near-black page, and black stays the text on it. */
[data-system="lime"][data-theme="dark"], .lime[data-theme="dark"], [data-theme="dark"] [data-system="lime"], [data-theme="dark"] .lime {
  --page: #0e0e0c;
  --surface: #1a1a17;
  --surface-2: #262622;
  --surface-3: #32322d;
  --raised: #1f1f1c;
  --field: #1a1a17;
  --scrim: rgb(0 0 0 / 0.64);

  --fg: #f4f3ee; /* 15.7:1 on --surface */
  --fg-2: #c9c7be;
  --fg-3: #9a9890; /* 5.3:1 on --surface-2 */
  --fg-disabled: #5e5d57;
  --fg-inverse: #0f0f0d;
  --on-accent: #0f0f0d;

  --line: #2e2e29;
  --line-strong: #3f3f39;
  --control: #8a8880; /* 4.9:1 on --surface */

  --ink: #f4f3ee;
  --ink-hover: #e1dfd7;
  --ink-active: #cfcdc4;

  --accent: #cad649; /* the lime a step calmer for a dark page: 12.2:1 on --page, 12.1:1 with --on-accent */
  --accent-hover: #d6e262;
  --accent-active: #bac534;
  --accent-wash: #2b2e0c; /* 12.6:1 with --fg */
  --accent-line: #cad649; /* the line step is the mark on dark */
  /* A switch's white knob on the lime needs a little more lift on a dark page. */
  --shadow-thumb: 0 2px 5px rgb(0 0 0 / 0.22), 0 1px 1px rgb(0 0 0 / 0.16), 0 0 0 0.5px rgb(0 0 0 / 0.2);

  --success: #4ade80;
  --success-tint: #12281a;
  --success-text: #6ee79b;
  --warn: #ffb224;
  --warn-tint: #2e2209;
  --warn-text: #ffc85c;
  --danger: #e5484d;
  --danger-hover: #d33a3f;
  --danger-tint: #2d1415;
  --on-danger: #0f0f0d;
  --danger-text: #ff8a8a;

  --shadow-ink: 0 0 0;
  --shadow-card: 0 1px 2px rgb(var(--shadow-ink) / 0.4);
  --shadow-menu: 0 8px 24px -6px rgb(var(--shadow-ink) / 0.6), 0 0 0 1px var(--line);
  --shadow-overlay: 0 24px 48px -12px rgb(var(--shadow-ink) / 0.7), 0 0 0 1px var(--line);

  --glow-accent-cast: 0 0 0;
  /* The glow on a dark page: the same calmer lime with ink on it, lit faintly, so it glows from inside instead of
     shining a light rim on the page. Black text is 9.8:1 or more at the darkest (pressed) stop. */
  --glow-accent-fg: #0f0f0d;
  --glow-accent-from: #c2cd3f;
  --glow-accent-to: #d1e376;
  --glow-accent-from-lit: #c8d447;
  --glow-accent-to-lit: #d8e983;
  --glow-accent-from-press: #b7c230;
  --glow-accent-to-press: #c6d65f;
  --glow-accent-light: 0.25;
  --glow-accent-edge: rgb(255 255 255 / 0.3);
  --glow-accent-bloom: rgb(255 255 255 / 0.12);
  --glow-accent-edge-lit: rgb(255 255 255 / 0.45);
  --glow-accent-bloom-lit: rgb(255 255 255 / 0.18);
  --glow-danger-from: #da474c; /* black text 4.9:1 at the worst point */
  --glow-danger-to: #f36a6f;
  --glow-danger-edge: rgb(255 255 255 / 0.5);
  --glow-danger-bloom: rgb(255 255 255 / 0.2);
  --glow-danger-cast: 0 0 0;
  --glow-danger-light: 1;
  --glow-danger-from-lit: #e45a5f; /* black text 5.9:1 */
  --glow-danger-to-lit: #f98285;
  --glow-danger-edge-lit: rgb(255 255 255 / 0.75);
  --glow-danger-bloom-lit: rgb(255 255 255 / 0.3);
  --glow-danger-from-press: #d24449; /* black text 4.6:1 */
  --glow-danger-to-press: #ec6368;
  --glow-success-from: #27a75d; /* black text 7.0:1 at the worst point */
  --glow-success-to: #55d88a;
  --glow-success-edge: rgb(255 255 255 / 0.5);
  --glow-success-bloom: rgb(255 255 255 / 0.2);
  --glow-success-cast: 0 0 0;
  --glow-success-light: 1;
  --glow-success-fg: #0f0f0d;
  --glow-success-from-lit: #32b96b;
  --glow-success-to-lit: #68e49b;
  --glow-success-edge-lit: rgb(255 255 255 / 0.75);
  --glow-success-bloom-lit: rgb(255 255 255 / 0.3);
  --glow-success-from-press: #1f8f4d; /* black text 5.3:1 */
  --glow-success-to-press: #43bf74;
}

/* Reduced motion zeroes every duration except the spinner, which is the only signal that work is running. */
@media (prefers-reduced-motion: reduce) {
  [data-system="lime"], .lime { --dur-instant: 0ms; --dur-fast: 0ms; --dur-base: 0ms; --dur-slow: 0ms; --scale-enter: 1; --scale-press: 1; }
}

/* Scoped base for Lime. Replaces Tailwind preflight inside .lime only; imported before the utilities. */

[data-system="lime"], .lime {
  background: var(--page);
  color: var(--fg);
  font-family: var(--font-sans);
  font-size: var(--text-sm);
  line-height: var(--leading-normal);
  font-weight: var(--weight-normal);
  text-wrap: pretty;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  color-scheme: light;
}
/* The same four dark selectors as tokens.css, so native controls and scrollbars turn dark with the tokens. */
[data-system="lime"][data-theme="dark"], .lime[data-theme="dark"], [data-theme="dark"] [data-system="lime"], [data-theme="dark"] .lime { color-scheme: dark; }
/* The reset sits in the base layer, beside Tailwind's own preflight, so a project's layered utilities (mx-auto,
   px-4) beat it, and Lime's unlayered ones still do. What must win over a page's own rules stays out of the layer:
   the scope element, the selection colour, the focus ring and the iOS zoom guard. */
@layer base {
  .lime :where(*, ::before, ::after), [data-system="lime"] :where(*, ::before, ::after) { box-sizing: border-box; border: 0 solid var(--line); margin: 0; padding: 0; }
  .lime :where(h1, h2, h3, h4, h5, h6, p, figure, blockquote, dl, dd, pre) { margin: 0; font: inherit; }
  .lime :where(ul, ol) { list-style: none; }
  .lime :where(a) { color: inherit; text-decoration: inherit; }
  .lime :where(button, input, select, textarea) { font: inherit; letter-spacing: inherit; color: inherit; background: transparent; }
  .lime :where(button, [role="button"]) { cursor: pointer; }
  .lime :where(button:disabled, [aria-disabled="true"]) { cursor: not-allowed; }
  .lime :where(img, video, canvas, svg) { display: block; max-width: 100%; }
  .lime :where(table) { border-collapse: collapse; }
  .lime :where(code, kbd, samp, pre) { font-family: var(--font-mono); }
  .lime :where(td, th, time, data, output) { font-variant-numeric: tabular-nums; }
  /* Every interactive element declares its transition, so no control cuts while its neighbour tweens. */
  .lime :where(a, button, summary, input, select, textarea, label, [role="button"], [role="tab"], [role="menuitem"], [role="option"], [role="switch"], [role="checkbox"], [role="radio"]) {
    transition-property: color, background-color, border-color, box-shadow, opacity;
    transition-duration: var(--dur-instant);
    transition-timing-function: var(--ease-out);
  }
  /* The ring's colour is set at rest, so a control that transitions its colours never fades the ring in from black. */
  .lime :where(*, ::before, ::after), [data-system="lime"] :where(*, ::before, ::after) { outline-color: var(--ring); }
}
.lime ::selection { background: var(--accent); color: var(--on-accent); }
/* Focus is a 2px outline in the accent's line step (3.95:1 on white), 2px out. Two classes of specificity beat a site-wide a:focus-visible. */
.lime :where(*):is(:focus-visible, [data-force-focus-visible]) { outline: var(--line-focus) solid var(--ring); outline-offset: var(--focus-offset); }
.lime, .lime * { scrollbar-color: var(--scrollbar-thumb) transparent; }

/* iOS Safari zooms the page when a field under 16px takes focus. On a coarse pointer every text field is at least 16px. */
@media (pointer: coarse) {
  .lime input:not([type="checkbox"], [type="radio"], [type="range"], [type="button"], [type="submit"], [type="file"]),
  .lime textarea,
  .lime select { font-size: max(16px, 1em); }
}

/* Lime's Tailwind entry. Import it once, in the root layout, as its own stylesheet.

   Scoping, so none of this reaches the rest of the page:
   - No preflight. The base rules in base.css apply inside .lime and [data-system="lime"] only.
   - The theme is `inline reference`: utilities compile to var(--lime-token) and nothing is written to
     :root, where the app may keep its own --color-*, --space-* and --font-* tokens.
   - Utilities come only from the folders the @source lines name (source(none)). Installed in a project, those are
     Lime's folders and the project's app, pages, src and components, so a Lime class in your own code works, and
     the utilities are nested under :where(.lime, [data-system="lime"]), so none of them reaches markup outside it.
   - base.css comes before the utilities, so a utility beats a base rule of the same specificity.
   - Utilities are unlayered on purpose. Unlayered rules beat every layer, so layered utilities would lose
     to an app's own unlayered `a` and `button` rules. */

@import "./tokens.css";
@import "./base.css";
:where(.lime, [data-system="lime"]) {
  @tailwind utilities source(none);
}

/* The folders to scan, but not the lint: it names every class Lime has and many it bans, and none of it is markup. */
@source "../../app";
@source "../../pages";
@source "../../src";
@source "../../components";
@source "../../lib/lime";
@source not "../../lib/lime/lint";

/* dark: matches inside the dark theme. Components never use it (tokens flip instead); it is here for
   one-off cases in your own markup. */
@custom-variant dark (&:where([data-theme="dark"], [data-theme="dark"] *));

/* A docs page or a test can show a state by setting data-force-hover, data-force-focus,
   data-force-focus-visible or data-force-active on a component's root. These variants
   answer to the attribute as well as the real pseudo-class, so a forced state is the component's own
   style, never a copy that drifts. Hover keeps Tailwind's guard: it only fires on devices that can hover. */
@custom-variant hover { @media (hover: hover) { &:hover { @slot; } } &[data-force-hover] { @slot; } }
@custom-variant focus { &:focus { @slot; } &[data-force-focus] { @slot; } }
@custom-variant focus-visible { &:focus-visible { @slot; } &[data-force-focus-visible] { @slot; } }
@custom-variant active { &:active { @slot; } &[data-force-active] { @slot; } }

/* The same goes for reduced motion: data-force-reduced-motion on a wrapper. motion-reduce: answers to it as
   well as the media query, and motion-safe: stands down under it. */
@custom-variant motion-reduce { @media (prefers-reduced-motion: reduce) { @slot; } &:where([data-force-reduced-motion], [data-force-reduced-motion] *) { @slot; } }
@custom-variant motion-safe { @media (prefers-reduced-motion: no-preference) { &:not(:where([data-force-reduced-motion], [data-force-reduced-motion] *)) { @slot; } } }

/* The same durations tokens.css zeroes under the media query, for a forced wrapper. */
.lime [data-force-reduced-motion], [data-system="lime"] [data-force-reduced-motion] { --dur-instant: 0ms; --dur-fast: 0ms; --dur-base: 0ms; --dur-slow: 0ms; --scale-enter: 1; --scale-press: 1; }

/* Glow: the one gradient in Lime. A solid accent body lit from inside.
   For the primary action, the balance chip and one featured card; never a background, text or an icon.
   - body: a darker top running to a bright bottom, so the light inside has something to read against.
   - top sheen, an off-centre bloom at the upper left, and a whisper of shade at the bottom edge.
   - a crisp highlight on the top edge, a light line on the lower edge, a faint white inner rim and an inner
     bloom; outside, only an olive hairline. It casts no shadow and no halo.
   - light pools at the bottom centre, so the surface reads as lit from below as well as above.
   - ::before holds the same stack, brighter, at opacity 0 and fades in on hover: the surface powers up
     without changing colour. Pressed swaps in a darker body. Disabled has no glow at all.
   Specificity is one class, scoped with :where, so a utility can still beat it. The colours are the
   --glow-* tokens in tokens.css, bound per hue by glow-accent, glow-danger and glow-success. */
:where(.lime, [data-system="lime"]) {
  .glow {
    position: relative;
    isolation: isolate;
    overflow: hidden;
    /* Layers, top to bottom, each one faint on its own:
       1. a sheen across the upper half       2. a bloom at the upper left
       3. light pooling at the bottom centre  4. a whisper of shade on the lowest edge
       5. the body, a darker top running to a bright bottom */
    background-image:
      linear-gradient(180deg, rgb(255 255 255 / calc(0.3 * var(--glow-light, 1))) 0%, rgb(255 255 255 / 0) 45%),
      radial-gradient(110% 90% at 22% 0%, rgb(255 255 255 / calc(0.24 * var(--glow-light, 1))) 0%, rgb(255 255 255 / 0) 60%),
      radial-gradient(70% 60% at 50% 115%, rgb(255 255 255 / calc(0.32 * var(--glow-light, 1))) 0%, rgb(255 255 255 / 0) 70%),
      linear-gradient(0deg, rgb(0 0 0 / 0.05) 0%, rgb(0 0 0 / 0) 18%),
      linear-gradient(180deg, var(--glow-from) 0%, var(--glow-to) 100%);
    /* Edges and light: a crisp highlight on the top edge, the light line on the lower edge, a faint white
       inner rim, the inner bloom, then outside only a hairline edge. No shadow or halo outside the button: a
       button never casts a shadow. */
    box-shadow:
      inset 0 1px 0 0 rgb(255 255 255 / calc(0.75 * var(--glow-light, 1))),
      inset 0 -1.5px 2px 0 var(--glow-edge),
      inset 0 0 0 1px rgb(255 255 255 / calc(0.2 * var(--glow-light, 1))),
      inset 0 0 12px 0 var(--glow-bloom),
      0 0 0 1px rgb(var(--glow-cast) / 0.22);
  }
  .glow::before {
    content: "";
    position: absolute;
    inset: 0;
    z-index: -1;
    border-radius: inherit;
    pointer-events: none;
    opacity: 0;
    transition: opacity var(--dur-base) var(--ease-out);
    background-image:
      linear-gradient(180deg, rgb(255 255 255 / calc(0.38 * var(--glow-light, 1))) 0%, rgb(255 255 255 / 0) 48%),
      radial-gradient(110% 95% at 22% 0%, rgb(255 255 255 / calc(0.3 * var(--glow-light, 1))) 0%, rgb(255 255 255 / 0) 62%),
      radial-gradient(75% 65% at 50% 115%, rgb(255 255 255 / calc(0.42 * var(--glow-light, 1))) 0%, rgb(255 255 255 / 0) 72%),
      linear-gradient(180deg, var(--glow-from-lit) 9%, var(--glow-to-lit) 100%);
    box-shadow:
      inset 0 1px 0 0 rgb(255 255 255 / calc(0.9 * var(--glow-light, 1))),
      inset 0 -0.5px 1px 0 var(--glow-edge-lit),
      inset 0 -1px 3px 0 var(--glow-edge-lit),
      inset 0 -1.5px 5px 0 var(--glow-edge-lit),
      inset 0 0 0 1px rgb(255 255 255 / calc(0.28 * var(--glow-light, 1))),
      inset 0 0 14px 0 var(--glow-bloom-lit);
  }
  /* Powered on. Only on a device that can hover, and data-force-hover forces it. */
  @media (hover: hover) { .glow:not(.glow-still):hover::before { opacity: 1; } }
  .glow:not(.glow-still)[data-force-hover]::before { opacity: 1; }

  /* Pressed: a darker body. The lit layer drops out and the base gradient takes the press colours. */
  .glow:not(.glow-still):is(:active, [data-force-active]) { --glow-from: var(--glow-press-from); --glow-to: var(--glow-press-to); }
  .glow:not(.glow-still):is(:active, [data-force-active])::before { opacity: 0; }

  /* Keep the label and icons above the overlay. */
  .glow > * { position: relative; z-index: 1; }

  /* Small and dense surfaces (a 32px button, the balance chip): keep the gradient and the lower edge line,
     drop the wide blooms, which turn to mud in the room they have. */
  .glow-subtle {
    box-shadow:
      inset 0 1px 0 0 rgb(255 255 255 / calc(0.7 * var(--glow-light, 1))),
      inset 0 -1px 1.5px 0 var(--glow-edge),
      inset 0 0 0 1px rgb(255 255 255 / calc(0.18 * var(--glow-light, 1))),
      inset 0 0 6px 0 var(--glow-bloom),
      0 0 0 1px rgb(var(--glow-cast) / 0.2);
  }
  .glow-subtle::before {
    box-shadow:
      inset 0 -0.5px 1px 0 var(--glow-edge-lit),
      inset 0 -1px 2.5px 0 var(--glow-edge-lit),
      inset 0 0 8px 0 var(--glow-bloom-lit);
  }

  /* Disabled has no glow: the gradient, the edge and the cast go, and the component's own disabled fill
     shows. A pending button is disabled too but keeps its colour, so aria-busy is left alone. */
  .glow:is(:disabled, [data-disabled], [aria-disabled="true"]):not([aria-busy="true"]) { background-image: none; box-shadow: none; }
  .glow:is(:disabled, [data-disabled], [aria-disabled="true"])::before { display: none; }

  .glow-accent {
    --glow-from: var(--glow-accent-from); --glow-to: var(--glow-accent-to);
    --glow-edge: var(--glow-accent-edge); --glow-bloom: var(--glow-accent-bloom);
    --glow-cast: var(--glow-accent-cast); --glow-light: var(--glow-accent-light);
    --glow-from-lit: var(--glow-accent-from-lit); --glow-to-lit: var(--glow-accent-to-lit);
    --glow-edge-lit: var(--glow-accent-edge-lit); --glow-bloom-lit: var(--glow-accent-bloom-lit);
    --glow-press-from: var(--glow-accent-from-press); --glow-press-to: var(--glow-accent-to-press);
    /* Text on the glow: ink on the bright light-theme body, white on the deep dark one. Flat accent fills keep --on-accent. */
    --on-accent: var(--glow-accent-fg);
  }
  .glow-danger {
    --glow-from: var(--glow-danger-from); --glow-to: var(--glow-danger-to);
    --glow-edge: var(--glow-danger-edge); --glow-bloom: var(--glow-danger-bloom);
    --glow-cast: var(--glow-danger-cast); --glow-light: var(--glow-danger-light);
    --glow-from-lit: var(--glow-danger-from-lit); --glow-to-lit: var(--glow-danger-to-lit);
    --glow-edge-lit: var(--glow-danger-edge-lit); --glow-bloom-lit: var(--glow-danger-bloom-lit);
    --glow-press-from: var(--glow-danger-from-press); --glow-press-to: var(--glow-danger-to-press);
  }
  .glow-success {
    --glow-from: var(--glow-success-from); --glow-to: var(--glow-success-to);
    --glow-edge: var(--glow-success-edge); --glow-bloom: var(--glow-success-bloom);
    --glow-cast: var(--glow-success-cast); --glow-light: var(--glow-success-light);
    --glow-from-lit: var(--glow-success-from-lit); --glow-to-lit: var(--glow-success-to-lit);
    --glow-edge-lit: var(--glow-success-edge-lit); --glow-bloom-lit: var(--glow-success-bloom-lit);
    --glow-press-from: var(--glow-success-from-press); --glow-press-to: var(--glow-success-to-press);
    color: var(--glow-success-fg);
  }
}

/* Forced colors drops backgrounds and shadows, so a state that only a fill or a ring carries disappears.
   These rules give each one a system color it keeps. They are the only forced-colors rules Lime has. Focus rings are outlines, which the browser keeps in
   forced colors; the rules here cover the places where focus or selection is carried by a fill or a border colour.
   They sit under the scope, because shadcn's own components use the same data-slot names outside it. */
@media (forced-colors: active) {
  :where(.lime, [data-system="lime"]) {
    .glow { background-image: none; box-shadow: none; border: 1px solid ButtonText; }
    .glow::before { display: none; }
    [data-slot="button"]:not([data-variant="link"]), [data-slot="copy-button"]:not([data-variant="link"]) { border: 1px solid ButtonText; }
    [data-slot="avatar"] { border: 1px solid CanvasText; }
    [data-slot="switch"][data-checked], [data-slot="checkbox"][data-checked], [data-slot="checkbox"][data-indeterminate], [data-slot="radio"][data-checked], [data-slot="segmented-item"][data-checked], [data-slot="chip"][data-pressed] { background-color: Highlight; border-color: Highlight; color: HighlightText; }
    [data-slot="switch-thumb"] { background-color: ButtonText; }
    [data-slot="switch"][data-checked] [data-slot="switch-thumb"] { background-color: HighlightText; }
    [data-slot="radio-indicator"] { background-color: HighlightText; }
    [data-slot="slider-track"] { background-color: GrayText; }
    [data-slot="slider-range"] { background-color: Highlight; }
    [data-slot="dropzone"][data-over] { outline: 2px solid Highlight; outline-offset: 2px; }
    [data-highlighted] { background-color: Highlight; color: HighlightText; }
    [data-slot="toolbar-toggle"][data-pressed] { background-color: Highlight; color: HighlightText; }
    [data-slot="tabs-indicator"] { background-color: Highlight; }
    [data-slot="chat-input"]:focus-within { outline: 2px solid Highlight; outline-offset: 2px; }
    [data-slot="select-trigger"][data-popup-open] { outline: 2px solid Highlight; outline-offset: 2px; }
    [data-slot="table-row"][data-state="selected"] { outline: 2px solid Highlight; outline-offset: -2px; }
  }
}


@theme inline reference {
  --*: initial;

  --breakpoint-sm: 640px;
  --breakpoint-md: 768px;
  --breakpoint-lg: 1024px;
  --breakpoint-xl: 1280px;

  --container-3xs: 16rem;
  --container-2xs: 18rem;
  --container-xs: 20rem;
  --container-sm: 24rem;
  --container-md: 28rem;
  --container-lg: 32rem;
  --container-xl: 36rem;
  --container-2xl: 42rem;
  --container-3xl: 48rem;
  --container-4xl: 56rem;
  --container-5xl: 64rem;
  --container-6xl: 72rem;
  --container-prose: 65ch;
  --container-popup: var(--popup-max);
  --container-overlay-sm: var(--overlay-sm);
  --container-overlay: var(--overlay);
  --container-overlay-lg: var(--overlay-lg);
  --container-popover: var(--popover);
  --container-sheet: var(--sheet);

  --aspect-video: 16 / 9;

  /* 4px base: p-1 is 4px, p-4 is 16px. */
  --spacing: 4px;

  --color-page: var(--page);
  --color-surface: var(--surface);
  --color-surface-2: var(--surface-2);
  --color-surface-3: var(--surface-3);
  --color-raised: var(--raised);
  --color-field: var(--field);
  --color-scrim: var(--scrim);
  --color-fg: var(--fg);
  --color-fg-2: var(--fg-2);
  --color-fg-3: var(--fg-3);
  --color-fg-disabled: var(--fg-disabled);
  --color-fg-inverse: var(--fg-inverse);
  --color-on-accent: var(--on-accent);
  --color-on-danger: var(--on-danger);
  --color-line: var(--line);
  --color-line-strong: var(--line-strong);
  --color-control: var(--control);
  --color-ink: var(--ink);
  --color-ink-hover: var(--ink-hover);
  --color-ink-active: var(--ink-active);
  --color-accent: var(--accent);
  --color-accent-hover: var(--accent-hover);
  --color-accent-active: var(--accent-active);
  --color-accent-wash: var(--accent-wash);
  --color-accent-line: var(--accent-line);
  --color-ring: var(--ring);
  --color-success: var(--success);
  --color-success-tint: var(--success-tint);
  --color-success-text: var(--success-text);
  --color-warn: var(--warn);
  --color-warn-tint: var(--warn-tint);
  --color-warn-text: var(--warn-text);
  --color-danger: var(--danger);
  --color-danger-hover: var(--danger-hover);
  --color-danger-tint: var(--danger-tint);
  --color-danger-text: var(--danger-text);
  --color-transparent: transparent;
  --color-current: currentColor;

  --font-sans: var(--font-sans);
  --font-mono: var(--font-mono);

  --font-weight-normal: var(--weight-normal);
  --font-weight-medium: var(--weight-medium);
  --font-weight-semibold: var(--weight-semibold);

  --text-xs: var(--text-xs);
  --text-xs--line-height: 16px;
  --text-sm: var(--text-sm);
  --text-sm--line-height: 20px;
  --text-base: var(--text-base);
  --text-base--line-height: 24px;
  --text-lg: var(--text-lg);
  --text-lg--line-height: 24px;
  --text-xl: var(--text-xl);
  --text-xl--line-height: 28px;
  --text-2xl: var(--text-2xl);
  --text-2xl--line-height: 34px;
  --text-3xl: var(--text-3xl);
  --text-3xl--line-height: 42px;

  --leading-tight: var(--leading-tight);
  --leading-snug: var(--leading-snug);
  --leading-normal: var(--leading-normal);
  --tracking-tight: var(--tracking-tight);
  --tracking-normal: 0em;

  --radius-sm: var(--radius-sm);
  --radius-md: var(--radius-md);
  --radius-field: var(--radius-field);
  --radius-panel: var(--radius-panel);
  --radius-sheet: var(--radius-sheet);
  --radius-control: var(--radius-control);
  --radius-full: 9999px;

  --shadow-card: var(--shadow-card);
  --shadow-menu: var(--shadow-menu);
  --shadow-overlay: var(--shadow-overlay);

  --ease-out: var(--ease-out);
  --ease-in: var(--ease-in);

  --animate-spin: lime-spin var(--dur-spin) linear infinite;
}

@keyframes lime-spin { to { transform: rotate(1turn); } }

/* Text roles: the size, weight, leading and tracking for each job, so a title or a caption is set the same way
   in every component. Color stays separate; pick it by role (text-fg, text-fg-2, text-fg-3). */
@utility title-page { @apply text-xl sm:text-2xl leading-tight font-semibold tracking-tight; }
@utility title-overlay { @apply text-xl leading-tight font-semibold tracking-tight; }
@utility label { @apply text-sm leading-snug font-medium; }
@utility body { @apply text-sm leading-normal font-normal; }
@utility caption { @apply text-xs font-normal; }
